n=19
objs=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
g=[[0]*n for _ in range(n)]
# horizontal then vertical
for r,c,v in objs:
    g[r]=[v]*n
for r,c,v in objs:
    for i in range(n): g[i][c]=v
# retain all original cross arms and centers
for r,c,v in objs:
    for rr,cc,x in [(r,c,v),(r-1,c,3),(r+1,c,3),(r,c-1,3),(r,c+1,3)]:
        g[rr][cc]=x
print('\n'.join(' '.join(map(str,row)) for row in g))

n=19
objs=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
arms={}
for r,c,v in objs:
    arms[(r-1,c)]=arms[(r+1,c)]=arms[(r,c-1)]=arms[(r,c+1)]=3
# extra hollow plus
for p in [(9,8),(11,8),(10,7),(10,9)]: arms[p]=3
h=[[0]*n for _ in range(n)]; vgrid=[[0]*n for _ in range(n)]
for r,c,val in objs:
    for dc in [-1,1]:
        x=c+dc
        while 0<=x<n:
            if (r,x) in arms and arms[(r,x)]==3 and not (abs(r-r)<=1 and abs(x-c)<=1):
                break
            h[r][x]=val
            x+=dc
    for dr in [-1,1]:
        y=r+dr
        while 0<=y<n:
            if (y,c) in arms and not (abs(y-r)<=1 and abs(c-c)<=1):
                break
            vgrid[y][c]=val
            y+=dr
    h[r][c]=val; vgrid[r][c]=val
out=[[h[i][j] or vgrid[i][j] for j in range(n)] for i in range(n)]
# Actually vertical wins when nonzero
for i in range(n):
 for j in range(n):
  if vgrid[i][j]: out[i][j]=vgrid[i][j]
# original 3s and centers overlay
for (r,c),val in arms.items(): out[r][c]=3
for r,c,val in objs: out[r][c]=val
# hollow center row-gap: all horizontal colored lines at c8 remain 0 unless vertical
for r,c,val in objs:
 if h[r][8] and not vgrid[r][8]: out[r][8]=0
print('\n'.join(' '.join(map(str,row)) for row in out))
